// n8n Code node: Braav Labs Outreach Doctrine prompt builder
// Shared verbatim by Code in JavaScript6 (sitemap-index path) and
// Code in JavaScript8 (direct-sitemap path).
const rawText = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
let s = String(rawText).trim();

// 1. Clean up JSON fences
s = s.replace(/```json/gi, '').replace(/```/g, '').trim();

// 2. Extract the JSON block from the vision output. A parse failure must not throw:
// a thrown error leaves the row unmarked and retries it forever.
let pages = [];
const m = s.match(/\{[\s\S]*\}/);
if (m) {
  try {
    const parsed = JSON.parse(m[0].trim());
    pages = Array.isArray(parsed.pages) ? parsed.pages : [];
  } catch (e) {
    pages = [];
  }
}

const cleanPages = pages.map(p => ({
  url: p.url ?? null,
  verdict: p.verdict ?? null,
  issues: Array.isArray(p.issues) ? p.issues.slice(0, 5) : [],
  quick_wins: Array.isArray(p.quick_wins) ? p.quick_wins.slice(0, 5) : []
}));

const pagesJson = JSON.stringify(cleanPages);

// 3. BRAAV LABS OUTREACH DOCTRINE PROMPT
const prompt =
  "You are the senior website-friction analyst and cold outreach copywriter for Braav Labs, an AI automation company working with dental, medical, and wellness clinics.\n" +
  "You are given website page issues from a screenshot review. Those issues are the ONLY allowed website problems. Do not invent anything that is not in VISION_PAGES_JSON.\n\n" +
  "GOAL: Pick ONE specific, observable friction on ONE page, tied to ONE next step (booking, inquiry, contact, consultation). The clinic owner should read it and think 'that's a fair point', then 'sure, send it over'.\n\n" +
  "HARD RULES:\n" +
  "- Never claim guaranteed revenue, conversion increases, or a measurable loss.\n" +
  "- Never claim access to analytics, traffic, or visitor data. No numbers, percentages, rates, or statistics of any kind.\n" +
  "- Never use marketing jargon: bounce rate, conversion, decision fatigue, choice overload, optimize, user experience, UX, funnel, revenue, ROI.\n" +
  "- Never pick an issue that could be a screenshot-capture artifact: counters or statistics showing 0, blank or black boxes, missing logos or images, empty sliders or carousels, content cut off at the bottom.\n" +
  "- Never pick a generic comment ('could be optimized', 'several issues', 'needs better AI'). The owner must be able to picture exactly where it is on the page.\n" +
  "- If no issue in VISION_PAGES_JSON is observable AND tied to a next step, do NOT make one up and do NOT use web search to find a substitute. Return website_problem as null.\n\n" +
  "COMPANY:\n" +
  "- Domain: " + $('Code in JavaScript1').first().json.website_domain + "\n" +
  "- Company Name: " + $('Get row(s) in sheet').first().json['Company Name'] + "\n\n" +
  "VISION_PAGES_JSON:\n" +
  pagesJson +
  "\n\n" +
  "FIELDS (plain language a clinic owner would say out loud):\n" +
  "- page: short page name (Home, About, Contact, Booking, Services...).\n" +
  "- website_problem: ONE sentence, max 25 words, ONE concrete observable issue on that page. No stacked issues.\n" +
  "- friction_summary: ONE sentence, max 20 words, naming that same friction and the one outcome the page is for. Example: 'making the booking button easy to find on mobile, so new patients can request a visit'.\n" +
  "- recognizable_reason: ONE sentence, max 30 words: one patient action + one hesitation trigger.\n" +
  "- recognizable_reason_short: the same reason, simpler, max 18 words.\n" +
  "- consequence_mechanics: ONE sentence, max 35 words, the cause-and-effect chain (patient arrives, next step feels unclear, they may leave without taking it). A plausible mechanism, never a claimed loss.\n" +
  "- consequence_short: the same chain, more direct, max 22 words.\n" +
  "- preview_asset_exists: true if a small before/after preview of this one fix is realistic, else false.\n" +
  "- review_time: integer minutes to look over that preview, 2 to 5.\n" +
  "- micro_yes: a short permission question about sending the free preview, max 8 words, e.g. 'Want me to send it over?'. Never offer to fix anything, never ask for a call or meeting, never mention price.\n" +
  "- subject_label: 3 to 4 words, plain business voice, names the same page/topic as website_problem, e.g. 'Homepage booking button'. No hype, no urgency, no punctuation, no ALL CAPS, no company name.\n\n" +
  "OUTPUT REQUIREMENTS (STRICT):\n" +
  "- Output MUST be valid JSON only. No markdown. No code fences. No extra keys.\n" +
  "- Return exactly these keys: page, website_problem, friction_summary, recognizable_reason, recognizable_reason_short, consequence_mechanics, consequence_short, preview_asset_exists, review_time, micro_yes, subject_label\n";

// 4. Escape for JSON embedding
const escapedPrompt = prompt
  .replace(/\\/g, '\\\\')
  .replace(/"/g, '\\"')
  .replace(/\r?\n/g, '\\\\n');

return [{ json: { prompt: escapedPrompt } }];

// n8n Code node: Final Variable Extractor + doctrine quality gate
// Shared verbatim by Code in JavaScript7 and Code in JavaScript9.
//
// Follow-ups need tightened variants of the same variables, so each cell holds
// "full || short". The outreach templates read part [0] or [1]. Rows that fail the
// gate get Issues = "Research failed" and are never emailed.
const raw =
  $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text ??
  $input.first().json?.text ??
  '';

let text = String(raw).trim().replace(/```json/gi, '').replace(/```/g, '').trim();

let obj = {};
const match = text.match(/\{[\s\S]*\}/);
if (match) {
  try {
    obj = JSON.parse(match[0].trim());
  } catch (e) {
    try { obj = JSON.parse(match[0].trim().replace(/,\s*([}\]])/g, '$1')); } catch (e2) { obj = {}; }
  }
}

const clean = v => (typeof v === 'string' ? v.replace(/\s*\|\|\s*/g, ' ').replace(/\s+/g, ' ').trim() : '');
const pack = (full, short) => (full ? full + ' || ' + (short || full) : '');

const page = clean(obj.page);
const problem = clean(obj.website_problem);
const summary = clean(obj.friction_summary).replace(/[.!]+$/, '');
const reason = clean(obj.recognizable_reason);
const reasonShort = clean(obj.recognizable_reason_short);
const cons = clean(obj.consequence_mechanics);
const consShort = clean(obj.consequence_short);
let micro = clean(obj.micro_yes);
let subject = clean(obj.subject_label).replace(/[!?.:;"]/g, '').trim();
let reviewTime = Number.isFinite(obj.review_time) ? Math.round(obj.review_time) : 3;
if (reviewTime < 2 || reviewTime > 5) reviewTime = 3;

// micro yes must stay a permission question about sending the preview
if (!micro || !/send/i.test(micro) || /\b(fix|call|meeting|chat|book a|schedule|price|cost)\b/i.test(micro) || micro.split(' ').length > 10) {
  micro = 'Want me to send it over?';
}
if (!micro.endsWith('?')) micro += '?';

const problems = [];
if (!page) problems.push('page');
if (!problem) problems.push('website_problem');
if (!reason) problems.push('recognizable_reason');
if (!cons) problems.push('consequence_mechanics');
if (!summary) problems.push('friction_summary');
const words = subject.split(' ').filter(Boolean).length;
if (words < 2 || words > 5) problems.push('subject_label');

const body = [problem, summary, reason, reasonShort, cons, consShort, subject].join(' ');
const banned = /\d+\s*%|\b\d+\+|bounce|conversion|revenue|\broi\b|decision fatigue|choice overload|analytics|guarantee|funnel|optimi[sz]/i;
if (banned.test(body)) problems.push('banned claim or metric');
const artifact = /counter|statistic|\b0\b|black|blank|placeholder|empty (media )?(box|player|space|area|section|profile|frame|slot)|broken (logo|image|photo|icon|video)|missing (a |an |the )?(logo|image|photo|headshot|picture|icon|video|thumbnail|portrait)|(no|without) (a |any )?(photo|headshot|picture|image|thumbnail|portrait)|carousel|slider|lazy|(not|fail\w*( to)?) load|cut off/i;
if (artifact.test(problem + ' ' + summary)) problems.push('possible screenshot artifact');

// A blocked or erroring page render is our own request being refused, not a defect
// the clinic can reproduce. Verified 2026-09-30: torontobeachdental.com returned a
// 403 to our server while serving HTTP 200 to an independent fetch, and the run
// wrote that block up as the clinic's website problem. Never ship it as a finding.
const blocked = /\bforbidden\b|\baccess denied\b|\bcloudflare\b|just a moment|checking your browser|attention required|site can'?t be reached|\b(40\d|5\d{2})\s*(error|forbidden|page|response|status)\b|\b(error|status)\s*(code\s*)?(40\d|5\d{2})\b/i;
const unreachable = /(site|website|homepage|web ?page|domain)\s+(is\s+)?(currently\s+)?(down|offline|unavailable|inaccessible|unreachable|not\s+(available|accessible|loading|working|reachable|functioning))/i;
if (blocked.test(body) || unreachable.test(body)) problems.push('blocked or error page, not reproducible');

const ok = problems.length === 0;

return [{
  json: {
    page,
    website_problem: pack(problem, summary),
    recognizable_reason: pack(reason, reasonShort),
    consequence_mechanics: pack(cons, consShort),
    preview_asset_exists: typeof obj.preview_asset_exists === 'boolean' ? obj.preview_asset_exists : null,
    review_time: reviewTime,
    micro_yes: micro,
    subject_label: subject,
    research_ok: ok,
    issues: ok ? '' : 'Research failed: ' + problems.join(', '),
    sources: $input.first().json?.groundingMetadata?.webSearchQueries ?? []
  }
}];

const items = $input.all();
const pending = items.filter(i => {
  const d = i.json.Done_Researched;
  return d === undefined || d === null || String(d).trim() === "";
});
return pending.length ? [pending[0]] : [];

function ok(b) {
  const t = String(b || '').slice(0, 5000).toLowerCase();
  if (!t) return false;
  if (t.includes('<!doctype html') || t.includes('<html') || t.includes('<head') || t.includes('<body')) return false;
  return t.includes('<?xml') && (t.includes('<sitemapindex') || t.includes('<urlset') || t.includes('<url><loc>'));
}
function grab(name) {
  try {
    const j = $(name).first().json;
    return (j && typeof j.data === 'string') ? j.data : '';
  } catch (e) {
    return '';
  }
}
const primary = grab('HTTP Request PRIMARY');
const fallback = grab('HTTP Request FALLBACK');
// Some hosts' WAFs answer the n8n server IP with 403 while serving the same
// sitemap to a browser, so a relay is tried before the row is written off.
const proxy = grab('Sitemap Proxy');

if (ok(primary)) return [{ json: { data: primary, sitemap_source: 'primary' } }];
if (ok(fallback)) return [{ json: { data: fallback, sitemap_source: 'fallback' } }];
if (ok(proxy)) return [{ json: { data: proxy, sitemap_source: 'proxy' } }];

// Nothing parsed. On these leads that is a WAF answering this server's IP - a
// Cloudflare interstitial or a flat 403 on /sitemap.xml - not a site without
// pages: the headless browser renders the same domains fine. Marking the row
// "Bad sitemap" discarded a reachable lead, so synthesise a one-entry urlset
// for the homepage and let the normal screenshot + research path run on it.
let home = '';
try { home = String($('Code in JavaScript').first().json.website_clean || '').trim(); } catch (e) { home = ''; }

if (!/^https?:\/\/[^ ]+$/i.test(home)) {
  // no usable homepage either - keep the old write-off behaviour
  return [{ json: { data: primary, sitemap_source: 'none' } }];
}

const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const synthetic =
  '<?xml version="1.0" encoding="UTF-8"?>\n' +
  '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
  '  <url><loc>' + esc(home) + '</loc></url>\n' +
  '</urlset>';

return [{ json: { data: synthetic, sitemap_source: 'synthetic-home' } }];

const src = $input.first().json;
let home = '';
try { home = String($('Code in JavaScript').first().json.website_clean || ''); } catch (e) { home = ''; }
const valid = u => typeof u === 'string' && /^https?:[/][/][^ ]+$/i.test(u.trim());
const picked = [];
const add = u => { if (valid(u) && picked.indexOf(u.trim()) < 0) picked.push(u.trim()); };
add(valid(src.url_1) ? src.url_1 : home);
add(src.url_2);
add(src.url_3);
add(home);
return picked.slice(0, 3).map((url, slot) => ({ json: { url, slot } }));

const src = $input.first().json;
let home = '';
try { home = String($('Code in JavaScript').first().json.website_clean || ''); } catch (e) { home = ''; }
const valid = u => typeof u === 'string' && /^https?:[/][/][^ ]+$/i.test(u.trim());
const picked = [];
const add = u => { if (valid(u) && picked.indexOf(u.trim()) < 0) picked.push(u.trim()); };
add(valid(src.url_1) ? src.url_1 : home);
add(src.url_2);
add(src.url_3);
add(home);
return picked.slice(0, 3).map((url, slot) => ({ json: { url, slot } }));

// Node "Sweep Pick" (Email automation) - v3.
// v1 retried a stuck row up to 3 times then silently ignored it forever. The row kept its
// failure text in Issues, so the watchdog went on counting it as stuck and would have emailed
// the same "failed-row count frozen" alert once every 24h for the rest of time.
// v2 gives up explicitly: after the last retry the row is stamped "Permanent: <reason>", which
// both this picker and the watchdog's stuck filter ignore. One visible mark in the sheet,
// no recurring alert, no human intervention.
// v3 adds RESET_TOKEN. The retry counters live in workflow static data, so rows that burned
// their three tries against a bug are unreachable even after that bug is fixed. Changing the
// token clears the counters exactly once, giving every stuck row a fresh set of tries under
// the repaired pipeline. Bump it whenever a fix changes what a retry can achieve.
const RESET_TOKEN = '2026-09-29-synthetic-sitemap-fallback';
const MAX_TRIES = 3;
const PER_SWEEP = 4;
const RETRYABLE = /bad sitemap|screenshot failed|research failed|timeout|rate limit/i;
const TERMINAL = /replied|unsubscrib|bounce|stop|no website/i;
const PERMANENT = /^\s*permanent/i;

const store = $getWorkflowStaticData('global');
if (store.sweepResetToken !== RESET_TOKEN) {
  store.sweep = {};
  store.gaveUp = {};
  store.sweepResetToken = RESET_TOKEN;
}
if (!store.sweep || typeof store.sweep !== 'object') store.sweep = {};
if (!store.gaveUp || typeof store.gaveUp !== 'object') store.gaveUp = {};
const tries = store.sweep;
const gaveUp = store.gaveUp;

const blank = v => v === undefined || v === null || String(v).trim() === '';
const rows = $input.all().map(i => i.json);

const stuck = rows.filter(r => {
  if (blank(r['Email Address'])) return false;
  if (!blank(r.ThreadID)) return false;
  const issues = String(r.Issues || '');
  if (PERMANENT.test(issues)) return false;        // already given up on
  if (!blank(issues) && TERMINAL.test(issues)) return false;
  const failed = !blank(issues) && RETRYABLE.test(issues);
  const oldFormat = blank(issues) && !blank(r.Done_Researched) && blank(r.Done)
    && !blank(r.website_problem) && !String(r.website_problem).includes(' || ');
  return failed || oldFormat;
});

const out = [];
const retried = [];
for (const r of stuck) {
  const key = String(r.row_number);
  const was = String(r.Issues || 'old format');
  const n = Number(tries[key] || 0);

  if (n >= MAX_TRIES) {
    // out of retries - stamp it once so nothing counts it as stuck again
    if (!gaveUp[key]) {
      gaveUp[key] = true;
      out.push({ json: {
        row_number: r.row_number,
        company: r['Company Name'] || '',
        mode: 'giveup',
        was: was,
        attempt: n,
        issues: 'Permanent: ' + was,
        dr: r.Done_Researched === undefined ? '' : r.Done_Researched,
        done: r.Done === undefined ? '' : r.Done,
        checked: r['Checked Reply'] === undefined ? '' : r['Checked Reply'],
      } });
    }
    continue;
  }

  if (retried.length >= PER_SWEEP) continue;
  tries[key] = n + 1;
  retried.push(key);
  out.push({ json: {
    row_number: r.row_number,
    company: r['Company Name'] || '',
    mode: 'retry',
    was: was,
    attempt: n + 1,
    issues: '', dr: '', done: '', checked: '',
  } });
}

return out;
